// JSON Pointer (RFC 6901) and JSON Patch (RFC 6902).

export class PatchError extends Error {
  constructor(message, index) {
    super(message);
    this.index = index;
  }
}
PatchError.prototype.name = 'PatchError';

const OPS = new Set(['add', 'remove', 'replace', 'move', 'copy', 'test']);
const INDEX_RE = /^(0|[1-9][0-9]*)$/;
const BAD_ESCAPE_RE = /~(?![01])/;

export function parsePointer(pointer) {
  if (typeof pointer !== 'string') throw new TypeError('pointer must be a string');
  if (pointer === '') return [];
  if (pointer[0] !== '/' || BAD_ESCAPE_RE.test(pointer)) throw new SyntaxError('invalid pointer');
  return pointer.slice(1).split('/').map((t) => t.replace(/~1/g, '/').replace(/~0/g, '~'));
}

function tryParsePointer(pointer) {
  if (typeof pointer !== 'string') return null;
  try {
    return parsePointer(pointer);
  } catch {
    return null;
  }
}

function isObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

// Sets an own data property; defineProperty keeps names such as `__proto__` ordinary.
function setMember(obj, name, value) {
  Object.defineProperty(obj, name, { value, writable: true, enumerable: true, configurable: true });
}

function clone(v) {
  if (Array.isArray(v)) return v.map(clone);
  if (isObject(v)) {
    const out = {};
    for (const k of Object.keys(v)) setMember(out, k, clone(v[k]));
    return out;
  }
  return v;
}

function kind(v) {
  if (v === null) return 'null';
  if (Array.isArray(v)) return 'array';
  return typeof v;
}

function equal(a, b) {
  const t = kind(a);
  if (t !== kind(b)) return false;
  if (t === 'array') return a.length === b.length && a.every((x, i) => equal(x, b[i]));
  if (t === 'object') {
    const keys = Object.keys(a);
    return keys.length === Object.keys(b).length
      && keys.every((k) => Object.hasOwn(b, k) && equal(a[k], b[k]));
  }
  return a === b;
}

function fail(index, reason) {
  return new PatchError(`operation ${index}: ${reason}`, index);
}

// Returns the value `token` names in `container`, or throws the matching failure.
function step(container, token, notFound, index) {
  if (Array.isArray(container)) {
    if (INDEX_RE.test(token)) {
      if (Number(token) < container.length) return container[Number(token)];
      throw fail(index, notFound);
    }
    throw fail(index, token === '-' ? notFound : 'bad index');
  }
  if (isObject(container) && Object.hasOwn(container, token)) return container[token];
  throw fail(index, notFound);
}

function resolve(root, tokens, notFound, index) {
  let v = root;
  for (const token of tokens) v = step(v, token, notFound, index);
  return v;
}

function addAt(root, tokens, value, index) {
  if (tokens.length === 0) return value;
  const parent = resolve(root, tokens.slice(0, -1), 'path not found', index);
  const last = tokens[tokens.length - 1];
  if (Array.isArray(parent)) {
    if (last === '-') {
      parent.push(value);
    } else if (INDEX_RE.test(last)) {
      if (Number(last) > parent.length) throw fail(index, 'path not found');
      parent.splice(Number(last), 0, value);
    } else {
      throw fail(index, 'bad index');
    }
  } else if (isObject(parent)) {
    setMember(parent, last, value);
  } else {
    throw fail(index, 'path not found');
  }
  return root;
}

// Follows `tokens` (at least one) and returns the parent and last token of the named value.
function locate(root, tokens, notFound, index) {
  const parent = resolve(root, tokens.slice(0, -1), notFound, index);
  const last = tokens[tokens.length - 1];
  step(parent, last, notFound, index);
  return { parent, last };
}

function removeAt(root, tokens, notFound, index) {
  const { parent, last } = locate(root, tokens, notFound, index);
  if (Array.isArray(parent)) parent.splice(Number(last), 1);
  else delete parent[last];
}

function sameTokens(a, b) {
  return a.length === b.length && a.every((t, i) => t === b[i]);
}

function isProperPrefix(prefix, tokens) {
  return prefix.length < tokens.length && prefix.every((t, i) => t === tokens[i]);
}

// Returns the form-rule reason the operation breaks, or a checked operation.
function checkForm(op) {
  if (typeof op !== 'object' || op === null || Array.isArray(op)) return { reason: 'not an object' };
  const name = Object.hasOwn(op, 'op') ? op.op : undefined;
  if (typeof name !== 'string' || !OPS.has(name)) return { reason: 'bad op' };
  const path = Object.hasOwn(op, 'path') ? tryParsePointer(op.path) : null;
  if (path === null) return { reason: 'bad path' };
  let from = null;
  if (name === 'move' || name === 'copy') {
    from = Object.hasOwn(op, 'from') ? tryParsePointer(op.from) : null;
    if (from === null) return { reason: 'bad from' };
  }
  const usesValue = name === 'add' || name === 'replace' || name === 'test';
  if (usesValue && !Object.hasOwn(op, 'value')) return { reason: 'missing value' };
  if (name === 'remove' && path.length === 0) return { reason: 'cannot remove root' };
  if (name === 'move' && isProperPrefix(from, path)) return { reason: 'cannot move into own child' };
  return { op: { name, path, from, value: usesValue ? op.value : undefined } };
}

function applyOperation(root, { name, path, from, value }, index) {
  switch (name) {
    case 'add':
      return addAt(root, path, clone(value), index);
    case 'remove':
      removeAt(root, path, 'path not found', index);
      return root;
    case 'replace': {
      if (path.length === 0) return clone(value);
      const { parent, last } = locate(root, path, 'path not found', index);
      if (Array.isArray(parent)) parent[Number(last)] = clone(value);
      else setMember(parent, last, clone(value));
      return root;
    }
    case 'move': {
      const moved = resolve(root, from, 'from not found', index);
      if (sameTokens(from, path)) return root;
      removeAt(root, from, 'from not found', index);
      return addAt(root, path, moved, index);
    }
    case 'copy':
      return addAt(root, path, clone(resolve(root, from, 'from not found', index)), index);
    case 'test':
      if (!equal(resolve(root, path, 'path not found', index), value)) throw fail(index, 'test failed');
      return root;
    default:
      throw new Error(`unreachable op ${name}`);
  }
}

export function applyPatch(doc, patch) {
  if (!Array.isArray(patch)) throw new PatchError('patch must be an array', null);
  const ops = [];
  for (let i = 0; i < patch.length; i++) {
    const checked = checkForm(patch[i]);
    if (checked.reason) throw fail(i, checked.reason);
    ops.push(checked.op);
  }
  let root = clone(doc);
  ops.forEach((op, i) => {
    root = applyOperation(root, op, i);
  });
  return root;
}
#!/usr/bin/env node
// Usage: node jsonpatch-cli.mjs <patch> [<doc>]
import fs from 'node:fs';
import { applyPatch, PatchError } from './jsonpatch.mjs';

const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]';
const MAX_BYTES = 1048576;
const MAX_DEPTH = 1000;

class CliError extends Error {
  constructor(message, exitCode) {
    super(message);
    this.exitCode = exitCode;
  }
}

function readError(name, reason) {
  return new CliError(`Error: ${name}: ${reason}`, 1);
}

function isDirectory(path) {
  try {
    return fs.statSync(path).isDirectory();
  } catch {
    return false;
  }
}

function readFileLimited(path) {
  let fd;
  try {
    fd = fs.openSync(path, 'r');
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
    if (err.code === 'EISDIR' || isDirectory(path)) throw readError(path, 'is a directory');
    throw readError(path, 'cannot read');
  }
  try {
    if (fs.fstatSync(fd).isDirectory()) throw readError(path, 'is a directory');
    const chunks = [];
    let total = 0;
    for (;;) {
      const buf = Buffer.alloc(65536);
      const n = fs.readSync(fd, buf, 0, buf.length, null);
      if (n === 0) break;
      total += n;
      if (total > MAX_BYTES) throw readError(path, 'too large');
      chunks.push(buf.subarray(0, n));
    }
    return Buffer.concat(chunks);
  } catch (err) {
    if (err instanceof CliError) throw err;
    if (err.code === 'EISDIR') throw readError(path, 'is a directory');
    throw readError(path, 'cannot read');
  } finally {
    fs.closeSync(fd);
  }
}

function readStdinLimited() {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    let stream;
    try {
      stream = process.stdin;
    } catch {
      reject(readError('stdin', 'cannot read'));
      return;
    }
    stream.on('data', (chunk) => {
      total += chunk.length;
      if (total > MAX_BYTES) {
        stream.destroy();
        reject(readError('stdin', 'too large'));
        return;
      }
      chunks.push(chunk);
    });
    stream.on('end', () => resolve(Buffer.concat(chunks)));
    stream.on('error', () => reject(readError('stdin', 'cannot read')));
  });
}

function jsonDepth(value) {
  let max = 0;
  const stack = [[value, 0]];
  while (stack.length > 0) {
    const [v, depth] = stack.pop();
    if (typeof v !== 'object' || v === null) continue;
    const d = depth + 1;
    if (d > max) max = d;
    if (max > MAX_DEPTH) return max;
    for (const child of Object.values(v)) stack.push([child, d]);
  }
  return max;
}

async function loadJson(arg) {
  const name = arg === '-' ? 'stdin' : arg;
  const bytes = arg === '-' ? await readStdinLimited() : readFileLimited(arg);
  let text;
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new CliError(`Error: ${name}: invalid UTF-8`, 3);
  }
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new CliError(`Error: ${name}: invalid JSON`, 3);
  }
  if (jsonDepth(value) > MAX_DEPTH) throw new CliError(`Error: ${name}: too deep`, 3);
  return value;
}

async function main(args) {
  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
  const [patchArg, docArg = '-'] = args;
  if (patchArg === '-' && docArg === '-') throw new CliError(USAGE, 2);
  const patch = await loadJson(patchArg);
  const doc = await loadJson(docArg);
  let result;
  try {
    result = applyPatch(doc, patch);
  } catch (err) {
    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
    throw err;
  }
  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
}

main(process.argv.slice(2)).catch((err) => {
  if (!(err instanceof CliError)) throw err;
  process.stderr.write(`${err.message}\n`);
  process.exitCode = err.exitCode;
});
# jsonpatch

A dependency-free JSON Pointer ([RFC 6901](https://www.rfc-editor.org/rfc/rfc6901)) and
JSON Patch ([RFC 6902](https://www.rfc-editor.org/rfc/rfc6902)) library and command-line tool
for Node.js.

## Library

```js
import { parsePointer, applyPatch, PatchError } from './jsonpatch.mjs';

parsePointer('/a~1b/~0c'); // ['a/b', '~c']

const doc = { b: 0 };
const result = applyPatch(doc, [
  { op: 'add', path: '/1', value: 5 },
  { op: 'test', path: '/b', value: 0 },
]);
// result: { '1': 5, b: 0 }; doc is unchanged

try {
  applyPatch({}, [{ op: 'remove', path: '/x' }]);
} catch (err) {
  if (err instanceof PatchError) console.log(err.message, err.index); // "operation 0: path not found" 0
}
```

- `parsePointer(pointer)` returns the decoded tokens. It throws a `TypeError`
  (`pointer must be a string`) when the pointer is not a primitive string, and a
  `SyntaxError` (`invalid pointer`) when the pointer is not valid.
- `applyPatch(doc, patch)` returns a new document. It never changes `doc` or `patch`, and the
  result shares no object or array with them. It checks the form of every operation before it
  applies any of them.
- `PatchError` has a `message` and an `index`: `index` is `null` for
  `patch must be an array`; otherwise it is the position of the failing operation and the
  message is `operation <i>: <reason>`.

Reasons: `not an object`, `bad op`, `bad path`, `bad from`, `missing value`,
`cannot remove root`, `cannot move into own child`, `path not found`, `from not found`,
`bad index`, `test failed`.

## Command line

```sh
node jsonpatch-cli.mjs <patch> [<doc>]
```

Reads the patch from `<patch>` and the document from `<doc>`. A missing `<doc>`, or an
argument of `-`, means standard input. The result is printed as JSON with 2-space indentation.

```sh
echo '{"b":0}' | node jsonpatch-cli.mjs patch.json
```

Inputs are UTF-8 (a leading byte order mark is ignored), at most 1 MiB and at most 1000
levels deep.

| Exit | Meaning |
| ---- | ------- |
| 0 | success |
| 1 | read error: `no such file`, `is a directory`, `too large`, `cannot read` |
| 2 | usage error (wrong argument count, or both inputs on standard input) |
| 3 | `invalid UTF-8`, `invalid JSON`, `too deep` |
| 4 | the patch failed: `Error: <PatchError message>` |

Errors are printed to stderr as one line, for example `Error: patch.json: no such file`.

## Tests

```sh
npm test
```

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const CLI = fileURLToPath(new URL('../jsonpatch-cli.mjs', import.meta.url));
const USAGE = 'Usage: node jsonpatch-cli.mjs <patch> [<doc>]\n';
let dir;

function run(args, input) {
  const r = spawnSync(process.execPath, [CLI, ...args], { cwd: dir, input: input ?? '' });
  return { code: r.status, stdout: r.stdout.toString(), stderr: r.stderr.toString() };
}

function write(name, content) {
  fs.writeFileSync(path.join(dir, name), content);
  return name;
}

function expectError(r, message, code) {
  assert.equal(r.stderr, `${message}\n`);
  assert.equal(r.stdout, '');
  assert.equal(r.code, code);
}

before(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsonpatch-cli-'));
  write('patch.json', '[{"op":"add","path":"/1","value":5}]');
  write('doc.json', '{"b":0}');
});

after(() => fs.rmSync(dir, { recursive: true, force: true }));

test('applies a patch from files', () => {
  const r = run(['patch.json', 'doc.json']);
  assert.equal(r.code, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, '{\n  "1": 5,\n  "b": 0\n}\n');
});

test('reads the document from stdin when missing or -', () => {
  assert.equal(run(['patch.json'], '{"b":0}').stdout, '{\n  "1": 5,\n  "b": 0\n}\n');
  assert.equal(run(['patch.json', '-'], '{"b":0}').stdout, '{\n  "1": 5,\n  "b": 0\n}\n');
  assert.equal(run(['-', 'doc.json'], '[]').stdout, '{\n  "b": 0\n}\n');
});

test('ignores a leading byte order mark', () => {
  write('bom.json', Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from('[]')]));
  assert.equal(run(['bom.json'], '?{"a":1}').stdout, '{\n  "a": 1\n}\n');
  write('bom2.json', Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf, 0xef, 0xbb, 0xbf]), Buffer.from('[]')]));
  expectError(run(['bom2.json'], '{}'), 'Error: bom2.json: invalid JSON', 3);
});

test('usage errors', () => {
  expectError(run([]), USAGE.trimEnd(), 2);
  expectError(run(['a', 'b', 'c']), USAGE.trimEnd(), 2);
  expectError(run(['-']), USAGE.trimEnd(), 2);
  expectError(run(['-', '-']), USAGE.trimEnd(), 2);
});

test('read errors', () => {
  expectError(run(['nope.json', 'doc.json']), 'Error: nope.json: no such file', 1);
  expectError(run(['patch.json/x', 'doc.json']), 'Error: patch.json/x: no such file', 1);
  fs.mkdirSync(path.join(dir, 'sub'), { recursive: true });
  expectError(run(['sub', 'doc.json']), 'Error: sub: is a directory', 1);
  expectError(run(['patch.json', 'nope.json']), 'Error: nope.json: no such file', 1);
});

test('too large inputs', () => {
  write('big.json', `[${' '.repeat(1048576 - 2)}]`);
  assert.equal(run(['big.json'], '1').code, 0);
  write('big2.json', `[${' '.repeat(1048576 - 1)}]`);
  expectError(run(['big2.json'], '1'), 'Error: big2.json: too large', 1);
  write('big3.json', Buffer.concat([Buffer.from([0xef, 0xbb, 0xbf]), Buffer.from(`[${' '.repeat(1048576 - 4)}]`)]));
  expectError(run(['big3.json'], '1'), 'Error: big3.json: too large', 1);
  expectError(run(['patch.json'], `"${'x'.repeat(1048576)}"`), 'Error: stdin: too large', 1);
});

test('decode, parse and depth errors', () => {
  write('bad-utf8.json', Buffer.from([0x5b, 0xff, 0x5d]));
  expectError(run(['bad-utf8.json', 'doc.json']), 'Error: bad-utf8.json: invalid UTF-8', 3);
  write('empty.json', '');
  expectError(run(['empty.json', 'doc.json']), 'Error: empty.json: invalid JSON', 3);
  expectError(run(['patch.json'], '{'), 'Error: stdin: invalid JSON', 3);
  write('deep1000.json', `${'['.repeat(1000)}${']'.repeat(1000)}`);
  assert.equal(run(['deep1000.json'], '1').code, 4);
  write('deep1001.json', `${'['.repeat(1001)}${']'.repeat(1001)}`);
  expectError(run(['deep1001.json', 'nope.json']), 'Error: deep1001.json: too deep', 3);
  expectError(run(['patch.json'], `${'{"a":'.repeat(1001)}1${'}'.repeat(1001)}`), 'Error: stdin: too deep', 3);
  expectError(run(['patch.json'], Buffer.from([0x22, 0xc3, 0x22])), 'Error: stdin: invalid UTF-8', 3);
});

test('the patch is fully checked before the document is read', () => {
  write('bad-patch.json', '{');
  expectError(run(['bad-patch.json', 'nope.json']), 'Error: bad-patch.json: invalid JSON', 3);
  expectError(run(['nope.json', 'bad-patch.json']), 'Error: nope.json: no such file', 1);
});

test('patch errors exit 4', () => {
  write('bad-op.json', '[{"op":"nope"}]');
  expectError(run(['bad-op.json', 'doc.json']), 'Error: operation 0: bad op', 4);
  write('not-array.json', '{}');
  expectError(run(['not-array.json', 'doc.json']), 'Error: patch must be an array', 4);
  write('test-fail.json', '[{"op":"test","path":"/b","value":1}]');
  expectError(run(['test-fail.json', 'doc.json']), 'Error: operation 0: test failed', 4);
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parsePointer, applyPatch, PatchError } from '../jsonpatch.mjs';

function patchError(doc, patch) {
  try {
    applyPatch(doc, patch);
  } catch (err) {
    assert.ok(err instanceof PatchError);
    assert.ok(err instanceof Error);
    assert.equal(err.name, 'PatchError');
    return err;
  }
  assert.fail('expected a PatchError');
}

function failsWith(doc, patch, message, index) {
  const err = patchError(doc, patch);
  assert.equal(err.message, message);
  assert.equal(err.index, index);
}

test('parsePointer decodes tokens', () => {
  assert.deepEqual(parsePointer(''), []);
  assert.deepEqual(parsePointer('/'), ['']);
  assert.deepEqual(parsePointer('/a//b/'), ['a', '', 'b', '']);
  assert.deepEqual(parsePointer('/~01'), ['~1']);
  assert.deepEqual(parsePointer('/~10'), ['/0']);
  assert.deepEqual(parsePointer('/a~1b/c~0d'), ['a/b', 'c~d']);
});

test('parsePointer returns a new array each time', () => {
  const a = parsePointer('');
  a.push('x');
  assert.deepEqual(parsePointer(''), []);
});

test('parsePointer rejects non-strings with TypeError', () => {
  for (const p of [new String('/a'), null, undefined, 1, ['/a'], {}]) {
    assert.throws(() => parsePointer(p), (e) => e instanceof TypeError && e.message === 'pointer must be a string');
  }
});

test('parsePointer rejects invalid pointers with SyntaxError', () => {
  for (const p of ['a', ' /a', '/~', '/~2', '/a~', '/~~0', '#/a']) {
    assert.throws(() => parsePointer(p), (e) => e instanceof SyntaxError && e.message === 'invalid pointer', p);
  }
});

test('patch must be an array', () => {
  for (const p of [null, {}, 'x', { length: 0 }, undefined]) {
    const err = patchError({}, p);
    assert.equal(err.message, 'patch must be an array');
    assert.equal(err.index, null);
  }
});

test('empty patch returns a deep copy keeping -0 and order', () => {
  const doc = { b: { c: [1, { d: -0 }] }, a: -0 };
  const out = applyPatch(doc, []);
  assert.deepEqual(out, doc);
  assert.notEqual(out, doc);
  assert.notEqual(out.b, doc.b);
  assert.notEqual(out.b.c, doc.b.c);
  assert.ok(Object.is(out.a, -0));
  assert.ok(Object.is(out.b.c[1].d, -0));
  assert.deepEqual(Object.keys(out), ['b', 'a']);
});

test('form rule: not an object', () => {
  for (const op of [null, [], 1, 'x', true, undefined, () => {}]) {
    failsWith({}, [op], 'operation 0: not an object', 0);
  }
  failsWith({}, [, { op: 'add' }], 'operation 0: not an object', 0); // eslint-disable-line no-sparse-arrays
  failsWith({}, [new String('x')], 'operation 0: bad op', 0);
  failsWith({}, [new Date()], 'operation 0: bad op', 0);
});

test('form rule: bad op', () => {
  for (const op of [{}, { op: 'ADD', path: '' }, { op: new String('add'), path: '', value: 1 }, { op: 'add ', path: '' }]) {
    failsWith({}, [op], 'operation 0: bad op', 0);
  }
  const inherited = Object.create({ op: 'test', path: '', value: {} });
  failsWith({}, [inherited], 'operation 0: bad op', 0);
});

test('non-enumerable own members count', () => {
  const op = {};
  Object.defineProperty(op, 'op', { value: 'add', enumerable: false });
  Object.defineProperty(op, 'path', { value: '/a', enumerable: false });
  Object.defineProperty(op, 'value', { value: 1, enumerable: false });
  assert.deepEqual(applyPatch({}, [op]), { a: 1 });
});

test('form rule: bad path and bad from', () => {
  failsWith({}, [{ op: 'remove' }], 'operation 0: bad path', 0);
  failsWith({}, [{ op: 'remove', path: new String('/a') }], 'operation 0: bad path', 0);
  failsWith({}, [{ op: 'remove', path: 'a' }], 'operation 0: bad path', 0);
  failsWith({}, [{ op: 'remove', path: '/~2' }], 'operation 0: bad path', 0);
  failsWith({}, [{ op: 'move', path: '/a' }], 'operation 0: bad from', 0);
  failsWith({}, [{ op: 'copy', path: '/a', from: 'x' }], 'operation 0: bad from', 0);
  failsWith({}, [{ op: 'move', path: 'x', from: 'x' }], 'operation 0: bad path', 0);
  // from is ignored on add
  assert.deepEqual(applyPatch({}, [{ op: 'add', path: '/a', value: 1, from: 5 }]), { a: 1 });
});

test('form rule: missing value', () => {
  for (const name of ['add', 'replace', 'test']) {
    failsWith({}, [{ op: name, path: '' }], 'operation 0: missing value', 0);
  }
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'replace', path: '/a', value: null }]), { a: null });
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'remove', path: '/a', value: undefined }]), {});
});

test('form rule: cannot remove root and cannot move into own child', () => {
  failsWith({}, [{ op: 'remove', path: '' }], 'operation 0: cannot remove root', 0);
  failsWith({ a: {} }, [{ op: 'move', from: '/a', path: '/a/b' }], 'operation 0: cannot move into own child', 0);
  failsWith({ a: {} }, [{ op: 'move', from: '', path: '/a' }], 'operation 0: cannot move into own child', 0);
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'move', from: '/a', path: '/ab' }]), { ab: 1 });
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'move', from: '', path: '' }]), { a: 1 });
});

test('form checks run on every operation before applying any', () => {
  failsWith({}, [{ op: 'test', path: '/x', value: 1 }, { op: 'nope' }], 'operation 1: bad op', 1);
});

test('form reasons are checked in order', () => {
  failsWith({}, [{ op: 'move', path: 'x' }], 'operation 0: bad path', 0);
  failsWith({}, [{ op: 'remove', path: '' , value: 1 }], 'operation 0: cannot remove root', 0);
});

test('add: object members and order', () => {
  const out = applyPatch({ b: 0 }, [{ op: 'add', path: '/1', value: 5 }]);
  assert.deepEqual(Object.keys(out), ['1', 'b']);
  const out2 = applyPatch({ a: 1, b: 2 }, [{ op: 'add', path: '/a', value: 3 }, { op: 'add', path: '/c', value: 4 }]);
  assert.deepEqual(Object.keys(out2), ['a', 'b', 'c']);
  assert.deepEqual(out2, { a: 3, b: 2, c: 4 });
});

test('add: special member names are ordinary', () => {
  const out = applyPatch({}, [{ op: 'add', path: '/__proto__', value: { x: 1 } }]);
  assert.ok(Object.hasOwn(out, '__proto__'));
  assert.equal(Object.getPrototypeOf(out), Object.prototype);
  assert.deepEqual(Object.keys(out), ['__proto__']);
  failsWith({}, [{ op: 'remove', path: '/toString' }], 'operation 0: path not found', 0);
  failsWith({}, [{ op: 'test', path: '/constructor', value: {} }], 'operation 0: path not found', 0);
  failsWith({}, [{ op: 'add', path: '/__proto__/x', value: 1 }], 'operation 0: path not found', 0);
});

test('add: whole document', () => {
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'add', path: '', value: [1] }]), [1]);
});

test('add: arrays', () => {
  assert.deepEqual(applyPatch([1, 2], [{ op: 'add', path: '/-', value: 3 }]), [1, 2, 3]);
  assert.deepEqual(applyPatch([1, 2], [{ op: 'add', path: '/1', value: 9 }]), [1, 9, 2]);
  assert.deepEqual(applyPatch([1, 2], [{ op: 'add', path: '/2', value: 9 }]), [1, 2, 9]);
  failsWith([1, 2], [{ op: 'add', path: '/3', value: 9 }], 'operation 0: path not found', 0);
  for (const t of ['01', '+1', '1.0', '1e0', ' 1', 'length', '', '-1']) {
    failsWith([1, 2], [{ op: 'add', path: `/${t}`, value: 9 }], 'operation 0: bad index', 0);
  }
});

test('add: parent missing or not a container', () => {
  failsWith({}, [{ op: 'add', path: '/a/b', value: 1 }], 'operation 0: path not found', 0);
  failsWith({ a: 1 }, [{ op: 'add', path: '/a/b', value: 1 }], 'operation 0: path not found', 0);
  failsWith('s', [{ op: 'add', path: '/0', value: 1 }], 'operation 0: path not found', 0);
  failsWith(null, [{ op: 'add', path: '/a', value: 1 }], 'operation 0: path not found', 0);
  failsWith([[]], [{ op: 'add', path: '/x/0', value: 1 }], 'operation 0: bad index', 0);
  failsWith([[]], [{ op: 'add', path: '/-/0', value: 1 }], 'operation 0: path not found', 0);
  failsWith([[]], [{ op: 'add', path: '/1/0', value: 1 }], 'operation 0: path not found', 0);
});

test('remove', () => {
  assert.deepEqual(applyPatch({ a: 1, b: 2 }, [{ op: 'remove', path: '/a' }]), { b: 2 });
  assert.deepEqual(applyPatch([1, 2, 3], [{ op: 'remove', path: '/0' }]), [2, 3]);
  failsWith([1], [{ op: 'remove', path: '/1' }], 'operation 0: path not found', 0);
  failsWith([1], [{ op: 'remove', path: '/-' }], 'operation 0: path not found', 0);
  failsWith([1], [{ op: 'remove', path: '/00' }], 'operation 0: bad index', 0);
  failsWith({ a: 1 }, [{ op: 'remove', path: '/b' }], 'operation 0: path not found', 0);
  failsWith({ a: 'str' }, [{ op: 'remove', path: '/a/0' }], 'operation 0: path not found', 0);
});

test('replace', () => {
  const out = applyPatch({ a: 1, b: 2 }, [{ op: 'replace', path: '/a', value: 9 }]);
  assert.deepEqual(Object.keys(out), ['a', 'b']);
  assert.deepEqual(out, { a: 9, b: 2 });
  assert.deepEqual(applyPatch([1, 2], [{ op: 'replace', path: '/1', value: 9 }]), [1, 9]);
  assert.equal(applyPatch({ a: 1 }, [{ op: 'replace', path: '', value: 5 }]), 5);
  failsWith({}, [{ op: 'replace', path: '/a', value: 1 }], 'operation 0: path not found', 0);
  failsWith([1], [{ op: 'replace', path: '/1', value: 1 }], 'operation 0: path not found', 0);
  failsWith([1], [{ op: 'replace', path: '/-', value: 1 }], 'operation 0: path not found', 0);
});

test('move', () => {
  assert.deepEqual(applyPatch({ a: 1, b: 2 }, [{ op: 'move', from: '/a', path: '/c' }]), { b: 2, c: 1 });
  assert.deepEqual(applyPatch([1, 2, 3], [{ op: 'move', from: '/0', path: '/2' }]), [2, 3, 1]);
  assert.deepEqual(applyPatch([1, 2, 3], [{ op: 'move', from: '/2', path: '/0' }]), [3, 1, 2]);
  // the index counts after removal: length is 2 after removing, so /3 is out of range
  failsWith([1, 2, 3], [{ op: 'move', from: '/0', path: '/3' }], 'operation 0: path not found', 0);
  const same = applyPatch({ a: 1, b: 2 }, [{ op: 'move', from: '/a', path: '/a' }]);
  assert.deepEqual(Object.keys(same), ['a', 'b']);
  failsWith({}, [{ op: 'move', from: '/x', path: '/x' }], 'operation 0: from not found', 0);
  failsWith({}, [{ op: 'move', from: '/x', path: '/y/z' }], 'operation 0: from not found', 0);
  failsWith([1], [{ op: 'move', from: '/a', path: '/0' }], 'operation 0: bad index', 0);
  failsWith({ a: 1 }, [{ op: 'move', from: '/a', path: '/y/z' }], 'operation 0: path not found', 0);
  assert.deepEqual(applyPatch({ a: { b: 1 } }, [{ op: 'move', from: '/a/b', path: '/a' }]), { a: 1 });
});

test('copy', () => {
  const out = applyPatch({ a: { b: [1] } }, [{ op: 'copy', from: '/a', path: '/a/c' }]);
  assert.deepEqual(out, { a: { b: [1], c: { b: [1] } } });
  assert.notEqual(out.a.b, out.a.c.b);
  assert.deepEqual(applyPatch({ a: 1 }, [{ op: 'copy', from: '', path: '/b' }]), { a: 1, b: { a: 1 } });
  failsWith({}, [{ op: 'copy', from: '/x', path: '/y' }], 'operation 0: from not found', 0);
  failsWith({ x: 1 }, [{ op: 'copy', from: '/x', path: '/y/z' }], 'operation 0: path not found', 0);
});

test('test: equality rules', () => {
  const ok = (doc, path, value) => assert.deepEqual(applyPatch(doc, [{ op: 'test', path, value }]), doc);
  const bad = (doc, path, value) => failsWith(doc, [{ op: 'test', path, value }], 'operation 0: test failed', 0);
  ok({ a: 1 }, '/a', 1.0);
  ok({ a: 0 }, '/a', -0);
  ok({ a: -0 }, '/a', 0);
  ok({ a: 1, b: [1, { c: null }] }, '', { b: [1, { c: null }], a: 1 });
  ok('x', '', 'x');
  bad({ a: 1 }, '/a', '1');
  bad({ a: '�' }, '/a', 'e'');
  bad({ a: [1, 2] }, '/a', [2, 1]);
  bad({ a: [1] }, '/a', [1, 1]);
  bad({ a: {} }, '/a', []);
  bad({ a: { x: 1 } }, '/a', { x: 1, y: 2 });
  bad({ a: { x: 1, y: 2 } }, '/a', { x: 1 });
  bad({ a: { x: 1 } }, '/a', { y: 1 });
  bad({ a: null }, '/a', false);
  bad({ a: 0 }, '/a', false);
  bad({ a: true }, '/a', 1);
  failsWith({}, [{ op: 'test', path: '/a', value: null }], 'operation 0: path not found', 0);
});

test('operations apply in order and report the failing index', () => {
  const patch = [
    { op: 'add', path: '/a', value: 1 },
    { op: 'test', path: '/a', value: 1 },
    { op: 'test', path: '/a', value: 2 },
  ];
  failsWith({}, patch, 'operation 2: test failed', 2);
});

test('applyPatch never changes doc or patch and shares nothing', () => {
  const doc = { a: [1, 2], b: { c: 1 } };
  const value = { deep: [1] };
  const patch = [
    { op: 'add', path: '/x', value },
    { op: 'remove', path: '/a/0' },
    { op: 'replace', path: '/b/c', value: [2] },
    { op: 'add', path: '/x/deep/-', value: 2 },
  ];
  const docCopy = structuredClone(doc);
  const patchCopy = structuredClone(patch);
  const out = applyPatch(doc, patch);
  assert.deepEqual(doc, docCopy);
  assert.deepEqual(patch, patchCopy);
  assert.deepEqual(out, { a: [2], b: { c: [2] }, x: { deep: [1, 2] } });
  assert.notEqual(out.x, value);
  failsWith(doc, [...patch, { op: 'test', path: '', value: 0 }], 'operation 4: test failed', 4);
  assert.deepEqual(doc, docCopy);
  assert.deepEqual(patch, patchCopy);
});

test('added values keep -0', () => {
  const out = applyPatch({}, [{ op: 'add', path: '/a', value: { b: -0 } }]);
  assert.ok(Object.is(out.a.b, -0));
});

test('handles 1000-level nesting', () => {
  let doc = 0;
  for (let i = 0; i < 1000; i++) doc = [doc];
  const out = applyPatch(doc, [{ op: 'copy', from: '', path: '/-' }, { op: 'test', path: '/0', value: doc[0] }]);
  assert.equal(out.length, 2);
});

